UPDATE companies SET description='Idaho Supreme Potatoes operates from Firth, Idaho, where it began as a fresh potato packing operation in 1967. The facility expanded into potato dehydration in 1969 and grew into one of North America''s dehydration plants. In 2018, Idaho Pacific Holdings acquired the company and continues its tradition of supplying dehydrated potato products worldwide.

The plant produces dehydrated potato flakes, flour, slices, dices, and shreds or hash browns, with ingredient specifications ranging from whole flake to finely milled flours, full cook to low leach, and additive-free clean label options. Foodservice lines include complete mashed potato mixes (blended or agglomerated), scalloped and au gratin casseroles, and seasoned or unseasoned hash browns. An in-house R&D team develops custom formulations, while packaging runs cover poly pouches, gabled cartons, #10 tins, kraft bags, polyethylene bulk sacks, and bulk rail or truck shipments. Private labeling is available for most foodservice and retail items.

The company sources Russet varieties such as Burbank, Norkotah, and Ranger from Idaho''s Snake River Plain, leveraging the region''s soil, water, and climate for consistent year-round supply.

Idaho Supreme Potatoes emphasizes its diverse production capabilities and certifications—GFSI, Orthodox Union kosher, and IFANCA halal—as the foundation for meeting varied technical and regulatory requirements.', certifications=ARRAY['GFSI approved standard','Kosher (Orthodox Union)','Halal (IFANCA)']::text[], profile='{"capabilities": ["Potato dehydration", "Flake production", "Flour milling", "Slicing", "Dicing", "Shredding/hash brown production", "Mashed potato mix blending", "Agglomeration", "Scalloped/au gratin casserole production", "Custom formulation (R&D)", "Packaging: poly pouches, gabled cartons, #10 tins, kraft bags, polyethylene bulk sacks", "Bulk rail shipping", "Bulk truck shipping", "Private labeling"], "industries": ["Foodservice", "Retail", "Food ingredients"], "materials": ["Potatoes", "Russet Burbank", "Russet Norkotah", "Russet Ranger"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Diverse dehydrated potato product line (flakes, flour, slices, dices, shreds)", "In-house R&D for custom formulations", "Flexible packaging from retail pouches to bulk rail", "Private labeling for foodservice and retail", "GFSI, Kosher (OU), and Halal (IFANCA) certifications"], "facts_used": ["Founded 1967 as fresh potato packing operation -> /", "Expanded to dehydration 1969 -> /", "Acquired by Idaho Pacific Holdings 2018 -> /", "Location Firth, Idaho -> /", "Products: dehydrated potato flakes, flour, slices, dices, shreds/hash browns -> /", "Foodservice products: mashed potato mixes, scalloped/au gratin casseroles, hash browns -> /", "R&D team for custom formulations -> /", "Packaging capabilities: poly pouches, gabled cartons, #10 tins, kraft bags, bulk sacks, bulk rail/truck -> /", "Private labeling available -> /", "Certifications: GFSI, Kosher (OU), Halal (IFANCA) -> /", "Potato varieties: Russet Burbank, Norkotah, Ranger -> /", "Shipping hours and warehouse address -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Idaho Supreme Potatoes manufactures dehydrated potato Flakes, Flour, Slices, Dices, and Shreds/Hash browns.", "founded_year": "1967", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='idaho-supreme-potatoes-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Idahound operates from Carey, Idaho, where it was founded in 2014. The company began as a wild dream to create a small-batch, farm-to-bowl dog food business, though the founders are not named in public materials.

The company custom butchers, processes, and packages all of its products in-house using grass-fed proteins sourced from ranches in southern Idaho. Its product line includes raw dog foods such as sheep and vegetable blends, green beef tripe, raw meaty lamb neck bones, hare balls, split elk antlers, lamb crisps, and rabbit treats. Frozen orders are insulated with locally manufactured hemp wool, reflecting a supply chain kept as local as possible.

Idahound sells directly to pet owners seeking biologically appropriate raw diets for dogs and cats. Customer testimonials highlight improved digestive health and long-term loyalty, with some buyers reporting ten years of repeat purchases. The company also manages subscription accounts for recurring deliveries.

The venture was built on a dual commitment to canine health and environmental stewardship. Idahound says its mission rests on compassion for dogs, the livestock that become their food, and the planet, aiming to promote responsible animal husbandry, sustainable agriculture, waste reduction, and the local food movement.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom butchering", "Meat processing", "In-house packaging", "Frozen order fulfillment", "Subscription management", "Raw pet food formulation"], "industries": ["Pet food manufacturing", "Raw pet food", "Direct-to-consumer pet food"], "materials": ["Grass-fed proteins (sheep, beef, lamb, rabbit, elk)", "Vegetables", "Hemp wool (insulation)"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Custom butchers, processes and packages all products in-house", "Uses locally manufactured hemp wool for frozen shipment insulation", "Small-batch, farm-to-bowl production model", "Focus on biologically appropriate raw diets for dogs and cats"], "facts_used": ["Founded in 2014 -> /", "Headquarters in Carey, Idaho -> db", "Custom butchers, processes, packages in-house -> /", "Sources proteins from Southern Idaho ranches -> /", "Uses locally manufactured hemp wool for insulation -> /", "Product line includes raw dog food (sheep, beef tripe, lamb, rabbit, elk antler) -> /", "Sells direct to pet owners, subscription model -> /", "Mission: canine health and environmental stewardship -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Using grass-fed proteins from local ranches, Idahound\u00ae custom butchers, processes and packages all of our products in-house.", "founded_year": "2014", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='idahound' AND approved AND profile IS NULL;
UPDATE companies SET description='Ideal Electric, Inc. was founded in 1994 in Winslow, Maine, a small community in the central part of the state. The company began as a modest electrical operation focused on serving homeowners and businesses throughout the region.

Today the firm provides a full range of electrical services across residential, commercial, and industrial sectors. Its licensed master and journeyman electricians handle panel upgrades, new‑construction wiring, EV‑charger installations, and whole‑home standby generator systems as a Generac‑certified dealer. The team also installs dedicated circuits for ductless heat‑pump systems certified through Efficiency Maine, and performs motor‑control wiring, high‑voltage work, and control‑panel assembly for industrial clients. Service and repair calls are offered for all three market segments.

The contractor serves customers across central Maine, including Waterville, Augusta, Skowhegan, Farmington, and surrounding towns. Its client base spans individual homeowners, commercial tenants needing fit‑outs and lighting retrofits, and industrial facilities requiring machine wiring and motor controls.

Ideal Electric emphasizes code‑compliant work, transparent pricing, and on‑time completion. The company holds Maine master and journeyman electrician licenses, Generac and Efficiency Maine certifications, and OSHA safety training, and carries full liability and workers’ compensation insurance on every project.', certifications=ARRAY['Maine Master Electrician License','Maine Journeyman Electrician License','Generac Certified Installer','Efficiency Maine Certified','OSHA Safety Trained']::text[], profile='{"capabilities": ["Residential electrical installation and repair", "Commercial tenant fit\u2011outs and lighting retrofits", "Industrial motor controls and high\u2011voltage wiring", "Standby generator installation and service (Generac)", "Ductless heat\u2011pump circuit wiring and installation", "Electrical panel upgrades and new\u2011construction wiring", "EV charger installation", "Control panel assembly", "Troubleshooting and service calls"], "industries": ["Residential", "Commercial", "Industrial"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Generac\u2011certified standby generator installation", "Efficiency Maine\u2011certified heat\u2011pump electrical work", "Maine master/journeyman electrician licenses on staff", "OSHA\u2011trained crews with full insurance", "Transparent, upfront pricing with no hidden fees"], "facts_used": ["Founded in 1994 -> /about", "Headquartered in Winslow, Maine -> /about", "Licensed master and journeyman electricians on staff -> /about", "Generac certified installer -> /about", "Efficiency Maine certified -> /about", "OSHA safety trained -> /about", "Services: residential, commercial, industrial electrical, standby generators, ductless heat pumps -> /services", "Service area: central Maine towns (Waterville, Augusta, Skowhegan, Farmington, etc.) -> /about", "Emphasis on code compliance, transparent pricing, on-time completion -> /about"], "company_type": "Installer / service company", "makes_products": "no", "type_evidence": "Ideal Electric, Inc. was founded in 1994 with a simple mission: deliver expert electrical work with the professionalism and integrity that central Maine homeowners and businesses deserve.", "founded_year": "1994", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='ideal-electric' AND approved AND profile IS NULL;
UPDATE companies SET description='Image Pointe was founded in 1977 in Waterloo, Iowa, as a supplier of custom-branded, union-made apparel and promotional products for labor unions across the United States. The company operates as a unionized workplace, with all graphics and production handled by members of IUPAT District Council 81, Local 246 and Workers United Local 38.

The company maintains an in-house art department and offers decoration services including screen printing and embroidery, producing items such as hoodies, sweatshirts, and thermal layers under its Dignity Apparel line, which is cut, sewn, and decorated domestically. Image Pointe employs over 80 people at its Waterloo facility, with a combined workforce of more than 150 when including Dignity Apparel operations in Iowa and Tennessee.

Its customer base consists primarily of labor unions and affiliated organizations; testimonials on the site reference the Columbus Education Association, UAW Local, and IBEW Charlotte. The company also serves unions seeking promotional products for events, awareness campaigns, and conventions.

Image Pointe emphasizes its mission to create dignified, life-changing jobs with fair wages and benefits, and it markets itself as the largest supplier of union and USA-made products, guaranteeing that all items are 100% made in the USA. The firm highlights average employee tenure of 15 years for graphic artists and 17 years for screen printers and embroidery operators as a marker of expertise.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom apparel decoration (screen printing, embroidery)", "In-house graphic design and art services", "Union-made promotional product sourcing", "Custom branded merchandise development", "Rapid order fulfillment and delivery", "Cut and sew manufacturing (Dignity Apparel line)", "Union-knit, union-cut & sewn, union-decorated apparel production"], "industries": ["Labor unions"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["100% union labor for all graphics and production", "USA-made products guaranteed; union-made wherever available", "In-house art department with decoration methods including screen printing and embroidery", "Mission-driven employment model focused on dignified, life-changing jobs", "Average 15 years'' experience for graphic artists, 17 years for production operators"], "facts_used": ["Founded 1977 -> db", "Headquarters Waterloo, Iowa -> db", "Largest supplier of union and USA-made products -> /", "Over 80 employees at Image Pointe, 150+ combined with Dignity Apparel -> /about-us", "Unionized by IUPAT DC 81 Local 246 and Workers United Local 38 -> /about-us", "In-house art department, decoration methods (screen printing, embroidery) -> /about-us, /", "Mission to create dignified, life-changing jobs -> /", "Customer testimonials from Columbus Education Association, UAW Local, IBEW Charlotte -> /", "Dignity Apparel line: union-knit, union-cut & sewn, union-decorated -> /", "Average 15 years graphic artist experience, 17 years screen printer/embroidery operator experience -> /about-us", "LinkedIn URL -> db"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "All graphics and production are created by union members, for union members to advance the union cause.", "founded_year": "1977", "employee_count": "80+ (150+ combined with Dignity Apparel)", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": ["https://www.linkedin.com/company/image-pointe/"], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='image-pointe' AND approved AND profile IS NULL;
UPDATE companies SET description='Imondi Foods is a family-owned wholesale bakery supplier headquartered in Lincoln, Rhode Island. The company was founded in 1984 by Tom Imondi, beginning with a pickup truck delivering fresh eggs on a handshake promise. It remains family-owned and operated, now led by the next generation including Kelsey Imondi and James Lanciotti.

The company distributes a comprehensive range of professional baking ingredients — flours, sugars, dairy, eggs, oils, chocolates, flavorings, mixes, and specialty items — to bakeries and food manufacturers across New England and eastern New York. Operations run from a 140,000-square-foot facility in Lincoln equipped with 20 loading docks and advanced refrigeration, supported by an 18-truck fleet that delivers five days a week throughout Rhode Island, Massachusetts, Connecticut, New Hampshire, Maine, New York, and New Jersey. The warehousing and distribution processes are SQF and Organic certified, with RSPO certification for sustainable palm oil.

Imondi Foods serves independent bakeries, commercial bakeries, and food manufacturers throughout the Northeast. Its customer base includes operations that rely on consistent, daily delivery of perishable and dry ingredients, with the company''s purchasing power enabling wholesale pricing across a broad product catalog.

